 roles=[p['role'] for p in real['predictions']];covered=sum(m['matched'] for m in real['matches']);roleok=sum(m.get('matched',False) and m.get('role_correct',False) for m in real['matches']);proc=ev['procedural_holdout'];f1=float(np.mean([x['f1'] for x in proc]));ious=[x['mean_instance_iou_on_matched'] for x in proc if x['mean_instance_iou_on_matched'] is not None]
